var raw = String($json.merged_response || (Array.isArray($json.content) && $json.content[0] && $json.content[0].text) || $json.text || "");
// DZ-19.2: JSON javob OXIRIDAN qidiriladi — oxirgi "}" gacha muvozanatli, "slaydlar" massivi bor eng oxirgi obyekt; oldidagi tahlil matni e'tiborsiz
function oxirgiJson(t){ var e = t.lastIndexOf("}"); while (e >= 0) { for (var s = t.lastIndexOf("{", e); s >= 0; s = s > 0 ? t.lastIndexOf("{", s - 1) : -1) { try { var o = JSON.parse(t.slice(s, e + 1)); if (o && Array.isArray(o.slaydlar)) return o; } catch (x) {} } e = e > 0 ? t.lastIndexOf("}", e - 1) : -1; } throw new Error("javobda slaydlar'li JSON topilmadi"); }
try { var reja = oxirgiJson(raw);
// DZ-9.4: muqova_ulush slaydida yorliq kod bilan majburlanadi (faktning raqami)
var KR = $("DZ · Komponent rejasi").first().json.komponent_rejasi || [];
// DZ-16.3: vizual_yorliq bo'sh bo'lsa — faktdagi birlik so'zi(lari) kod bilan (KATTA); sarlavhadagi so'zlar chiqariladi; bo'lmasa bo'sh qoladi (raqam kattalashadi)
(function(){ var FK = ($("DZ · Komponent rejasi").first().json.faktlar) || [];
  function lw(t){ return String(t||"").replace(/İ/g,"i").replace(/I/g,"ı").toLowerCase(); }
  (reja.slaydlar||[]).forEach(function(sl){ if (!sl || !sl.komponent || String(sl.vizual_yorliq||"").trim()) return; if (["K_KARTA","K_QADAM","K_IQTIBOS"].indexOf(sl.komponent) >= 0) return;
    var f = FK.filter(function(x){ return x.s_id === sl.s_id; })[0]; if (!f) return;
    var sr = (lw(sl.sarlavha).match(/[a-zçğıöşüâîû]+/g) || []).map(function(x){ return x.slice(0,5); });
    var ws = (String(f.ekran||"").match(/[A-Za-zÇĞİÖŞÜçğıöşüâîû]+/g) || []).filter(function(x){ return sr.indexOf(lw(x).slice(0,5)) < 0; });
    if (ws.length && ws.length <= 4) { sl.vizual_yorliq = ws.join(" ").toLocaleUpperCase("tr"); sl.vizual_yorliq_kod = true; } }); })();
// DZ-15 Z5: K_KARTA slaydida sarlavha chizilmaydi — olib tashlanadi (FAIL emas)
(reja.slaydlar||[]).forEach(function(sl){ if (sl && sl.komponent === "K_KARTA" && sl.sarlavha) { sl.sarlavha_olib_tashlandi = sl.sarlavha; sl.sarlavha = ""; } });
// DZ-14 A1: K_RAQAM tavsifi faqat vizual_yorliq'da — komponent_malumot.yorliq olib tashlanadi
(reja.slaydlar||[]).forEach(function(sl){ if (sl && sl.komponent === "K_RAQAM" && sl.komponent_malumot && "yorliq" in sl.komponent_malumot) { delete sl.komponent_malumot.yorliq; } });
KR.forEach(function(p, i){ if (!p.yorliq_majburiy) return; var sl = (reja.slaydlar||[])[i]; if (!sl) return; var d = sl.komponent_malumot || {}; var son = (String(p.yorliq_majburiy).match(/\d+([.,]\d+)*/)||[""])[0]; var yor = String(d.yorliq || ""); if (!son || yor.indexOf(son) < 0) { d.yorliq = p.yorliq_majburiy; sl.yorliq_kod_toldirdi = true; } sl.komponent_malumot = d; });
return { json: Object.assign({}, $("DZ · Komponent rejasi").first().json, { reja: reja }) }; }
catch(err){ return { json: { xato:true, tur:"PARSE_FAIL", xabar:String(err).slice(0,200), raw: raw.slice(0,500) } }; }

