var j = $json;
var kir = $("DZ · Kirish tayyor").first().json;
var X = [];
if (j.xato) { X.push("PARSE_FAIL: art-direktor javobi JSON emas"); }
var reja = (j.reja || {}), S = reja.slaydlar || [];
var manba = (function(){ try { return $("DZ · Komponent rejasi").first().json.slaydlar || kir.slaydlar || []; } catch(e) { return kir.slaydlar || []; } })(); // DZ-10.2: tanlangan slaydlar
var ARX = ["A1_MUQOVA","A2_DALIL","A3_TEZIS","A4_YAKUN","P1_POSTER","A5_MANIFEST"];
var KOM = ["K_RAQAM","K_TAQQOS","K_KARTA","K_QADAM","K_USTUN","K_KESISH","K_KVADRAT","K_DONUT","K_ORALIQ","K_IQTIBOS"];
function norm(s){ return String(s||"").replace(/\s+/g,"").toLowerCase(); }
// ===== DZ-3 yordamchilari =====
function low(t){ t = String(t||""); try { return t.toLocaleLowerCase("tr"); } catch(e) { return t.replace(/İ/g,"i").replace(/I/g,"ı").toLowerCase(); } }
function nrm(t){ return low(t).replace(/[^0-9a-zçğıöşüâîû%€$]+/g," ").replace(/\s+/g," ").trim(); }
function tson(t){ t = String(t); if (/^\d{1,3}(\.\d{3})+$/.test(t)) return Number(t.replace(/\./g,"")); return Number(t.replace(",", ".")); }
function sontok(t){ return String(t||"").match(/\d+([.,]\d+)*/g) || []; }
function sonlar(a){ return (Array.isArray(a)?a:[]).map(function(x){ return typeof x==="number" ? x : tson(String(x).replace(/[^\d.,]/g,"")); }); }
var faktSon = [];
(kir.faktlar||[]).forEach(function(f){ sontok(f.ekran).forEach(function(t){ faktSon.push(tson(t)); }); });
function faktda(x){ x = Number(x); return isFinite(x) && faktSon.some(function(y){ return Math.abs(y - x) < 1e-9; }); }
function faktEkran(id){ var f = (kir.faktlar||[]).filter(function(q){ return q.s_id === id; })[0]; return f ? String(f.ekran||"") : ""; }
var DAROMAD = /y[ıi]ll[ıi]k|getiri|geride|gerisinde/;      // DZ-3.5: daromad/farq foizi ("kayıp oranı" — ulush, bunga kirmaydi)
var TEKIS = /de[gğ]i[sş]me(di|z|miyor|yen)|(^|[^a-zçğıöşü])ayn[ıi]([^a-zçğıöşü]|$)|(^|[^a-zçğıöşü])sabit|o['‘’\u0060]?zgarma(di|gan|ydi)/; // DZ-3.2c
var QREG = /["“”«»„]([^"“”«»„]{3,})["“”«»„]/g;           // DZ-3.3: qo'shtirnoq ichidagi gaplar
var tirnoq = [];
manba.map(function(m){ return (m.sarlavha||"") + " " + (m.tana||""); }).concat((kir.faktlar||[]).map(function(f){ return (f.ekran||"") + " " + (f.manba_toliq||""); })).forEach(function(t){ var m; QREG.lastIndex = 0; while ((m = QREG.exec(t))) tirnoq.push(nrm(m[1])); });
function ustma(a, b){ a = nrm(a); b = nrm(b); if (a.length < 8 || b.length < 8) return false; if (a.indexOf(b) >= 0 || b.indexOf(a) >= 0) return true; var A = a.split(" ").filter(function(w){ return w.length > 2; }), B = b.split(" "); if (A.length < 3) return false; return A.filter(function(w){ return B.indexOf(w) >= 0; }).length / A.length >= 0.7; }
function tekis(l){ return l.length >= 2 && l.every(function(x){ return x === l[0]; }); }
if (!j.xato) {
  if (S.length !== manba.length) X.push("a) slaydlar soni " + S.length + ", kerak " + manba.length);
  S.forEach(function(s, i){
    var src = manba[i] || manba.filter(function(m){ return m.n === s.n; })[0] || {};
    var soz = function(t){ return String(t||"").toLowerCase().replace(/[.,;:!?()«»"“”…→]/g," ").split(/\s+/).filter(Boolean); };
    var korpus = soz(manba.map(function(m){ return m.sarlavha + " " + m.tana + " " + m.vizual; }).join(" ") + " " + (kir.faktlar||[]).map(function(f){ return (f.ekran||"") + " " + (f.manba||"") + " " + (f.manba_toliq||""); }).join(" "));
    var xom = manba.map(function(m){ return m.sarlavha + " " + m.tana + " " + m.vizual; }).join(" ") + " " + (kir.faktlar||[]).map(function(f){ return (f.ekran||"") + " " + (f.manba||"") + " " + (f.manba_toliq||""); }).join(" "); var raqamlar = xom.match(/\d+([.,]\d+)*/g) || [];
    var lev = function(x,y){ if (Math.abs(x.length-y.length) > 2) return 9; var d=[]; for (var p=0;p<=x.length;p++){ d[p]=[p]; } for (var q=0;q<=y.length;q++){ d[0][q]=q; } for (p=1;p<=x.length;p++) for (q=1;q<=y.length;q++) d[p][q]=Math.min(d[p-1][q]+1,d[p][q-1]+1,d[p-1][q-1]+(x[p-1]===y[q-1]?0:1)); return d[x.length][y.length]; };
    ["sarlavha","matn"].forEach(function(f){
      var sozlar = soz(s[f]);
      (String(s[f]||"").match(/\d+([.,]\d+)*/g) || []).forEach(function(r){ if (raqamlar.indexOf(r) < 0) X.push("b) " + (i+1) + "-slayd " + f + ": manbada yo'q raqam — " + r); });
      sozlar.forEach(function(sw){ if (sw.length < 5 || korpus.indexOf(sw) >= 0) return; var yaqin = korpus.filter(function(k){ return k.length >= 5 && k.slice(0,2) === sw.slice(0,2) && lev(k, sw) > 0 && lev(k, sw) <= 2 && k.slice(0, Math.min(k.length, sw.length) - 3) !== sw.slice(0, Math.min(k.length, sw.length) - 3); }); if (yaqin.length) X.push("b) " + (i+1) + "-slayd " + f + ": imlo xatosi bo'lishi mumkin — \"" + sw + "\" (manbada: \"" + yaqin[0] + "\")"); });
    });
    var ikkiRaqam = /\d\s*[-–]\s*[%€$]?\s*\d/.test(String(s.raqam||"")) && String(s.raqam||"").indexOf("%") >= 0; // oraliq faqat "raqam–raqam"; "%6,5" — bitta qiymat
    var foiz = String(s.raqam||"").indexOf("%") >= 0;
    var daromad = foiz && DAROMAD.test(low([s.raqam, s.sarlavha, faktEkran(s.s_id)] /* src emas: slayd tartibi siljishi mumkin */.join(" "))); // DZ-3.5
    if (s.arxetip !== "A1_MUQOVA" && s.arxetip !== "A4_YAKUN") {
      if (daromad) { if (["K_RAQAM","K_TAQQOS"].indexOf(s.komponent) < 0) X.push("i) " + (i+1) + "-slayd: daromad/farq foizi (" + s.raqam + ") — K_RAQAM yoki K_TAQQOS ishlat (0–100 shkala va kvadrat — faqat ulush uchun)"); }
      else if (ikkiRaqam && s.komponent !== "K_ORALIQ") X.push("i) " + (i+1) + "-slayd: oraliq (" + s.raqam + ") uchun K_ORALIQ ishlat");
      else if (!ikkiRaqam && foiz && ["K_KVADRAT","K_DONUT"].indexOf(s.komponent) < 0) X.push("i) " + (i+1) + "-slayd: foiz (" + s.raqam + ") — K_KVADRAT yoki K_DONUT ishlat");
    }
    if (ARX.indexOf(s.arxetip) < 0) X.push("h) " + (i+1) + "-slayd arxetip noma'lum: " + s.arxetip);
    if (s.komponent && KOM.indexOf(s.komponent) < 0) X.push("h) " + (i+1) + "-slayd komponent noma'lum: " + s.komponent);
    if (i > 0 && s.komponent && s.komponent !== "K_ORALIQ" && S[i-1].komponent === s.komponent) X.push("c) " + i + "- va " + (i+1) + "-slayd bir xil komponent " + s.komponent);
    if (s.raqam && s.s_id && (kir.faktlar||[]).map(function(f){return f.s_id;}).indexOf(s.s_id) < 0) X.push("f) " + (i+1) + "-slayd s_id faktlarda yo'q: " + s.s_id);
    if (s.raqam && !s.s_id) X.push("f) " + (i+1) + "-slayd raqam bor, s_id yo'q");

    // ===== DZ-3 tekshiruvlari =====
    var n = (i+1) + "-slayd", K = s.komponent, dd = s.komponent_malumot || {};
    // DZ-3.2a/b: komponent ma'lumoti — faqat haqiqiy, faktlardagi raqamlar; bo'lmasa komponent chizilmaydi → FAIL
    var dv = sonlar(dd.degerler), la = sonlar(dd.a), lb = sonlar(dd.b);
    if (K === "K_USTUN") { if (dv.filter(isFinite).length < 2) X.push("k) " + n + ": K_USTUN uchun degerler yo'q"); else dv.forEach(function(x){ if (!faktda(x)) X.push("k) " + n + ": K_USTUN degerler faktlarda yo'q son — " + x); }); }
    if (K === "K_TAQQOS") { var A = Number(dd.a), B = Number(dd.b); if (dd.a == null || dd.b == null || !isFinite(A) || !isFinite(B)) X.push("k) " + n + ": K_TAQQOS uchun a/b yo'q"); else [A,B].forEach(function(x){ if (!faktda(x)) X.push("k) " + n + ": K_TAQQOS faktlarda yo'q son — " + x); }); }
    if (K === "K_KESISH") { if (la.filter(isFinite).length < 2 || lb.filter(isFinite).length < 2) X.push("k) " + n + ": K_KESISH uchun a/b chiziq sonlari yo'q"); else la.concat(lb).forEach(function(x){ if (!faktda(x)) X.push("k) " + n + ": K_KESISH faktlarda yo'q son — " + x); }); }
